__JANUSMASK_MANIFEST__ = {
    'harness/webui_config_schema.py': r'''"""Declarative configuration schema and server-side validation for WebUI settings."""

from dataclasses import dataclass, field
from typing import Any, Optional, Union
import os
from pathlib import Path
from tempfile import NamedTemporaryFile
import yaml


class ConfigValidationError(Exception):
    """Exception raised when configuration validation fails."""
    def __init__(self, field_errors: dict[str, str]):
        super().__init__(f"Config validation failed: {field_errors}")
        self.field_errors = field_errors


@dataclass
class ValidatedConfig:
    """Wrapper for successfully validated configuration values."""
    values: dict


@dataclass
class ConfigField:
    """Declaration of a single typed configuration field."""
    name: str
    dtype: str
    default: Any
    choices: Optional[Any] = field(default=None, kw_only=True)
    min: Optional[Any] = field(default=None, kw_only=True)
    max: Optional[Any] = field(default=None, kw_only=True)
    role: Optional[str] = field(default=None, kw_only=True)


@dataclass
class RoleSpec:
    """Specification of an agent role in configuration."""
    name: str
    config_key: str
    dual: bool


@dataclass
class ProviderSpec:
    """Specification of a model provider."""
    provider_id: str
    label: str
    api_key_env: Optional[str]
    api_backed: bool


CONFIG_FIELDS = [
    ConfigField(name="parallel_cap", dtype="int", default=4, min=1, max=16),
    ConfigField(name="min_ram_mb", dtype="int", default=1024, min=0),
    ConfigField(name="cooldown_tier_1", dtype="float", default=100.0, min=0.0),
    ConfigField(name="cooldown_tier_2", dtype="float", default=1000.0, min=0.0),
    ConfigField(name="cooldown_tier_3", dtype="float", default=10000.0, min=0.0),
    ConfigField(name="antigravity_mode", dtype="bool", default=False),
    ConfigField(name="sandbox.filesystem_root", dtype="path-dir", default="/tmp/janusmask_sandbox"),
    ConfigField(name="overseer.store_path", dtype="path-file", default="state/overseer/store.json"),
]

ROLES = [
    RoleSpec(name="synthesis", config_key="synthesis.active_agents", dual=True),
    RoleSpec(name="overseer", config_key="overseer.default_backend", dual=False),
    RoleSpec(name="autobrief", config_key="control.autobrief_default_agent", dual=False),
]

PROVIDERS = {
    "claude": ProviderSpec("claude", "Claude (CLI)", None, False),
    "gemini": ProviderSpec("gemini", "Gemini (CLI)", None, False),
    "antigravity": ProviderSpec("antigravity", "Antigravity (CLI)", None, False),
    "codex": ProviderSpec("codex", "Codex (CLI)", None, False),
    "openai": ProviderSpec("openai", "OpenAI API", "OPENAI_API_KEY", True),
    "gemini_api": ProviderSpec("gemini_api", "Gemini API", "GEMINI_API_KEY", True),
    "anthropic": ProviderSpec("anthropic", "Anthropic API", "ANTHROPIC_API_KEY", True),
    "deepseek": ProviderSpec("deepseek", "DeepSeek API", "DEEPSEEK_API_KEY", True),
    "moonshot": ProviderSpec("moonshot", "Moonshot API", "MOONSHOT_API_KEY", True),
    "zhipu": ProviderSpec("zhipu", "Zhipu GLM API", "ZHIPU_API_KEY", True),
    "qwen": ProviderSpec("qwen", "Qwen/DashScope API", "DASHSCOPE_API_KEY", True),
    "minimax": ProviderSpec("minimax", "MiniMax API", "MINIMAX_API_KEY", True),
}


def coerce_value(val: Any, field: ConfigField) -> Any:
    dtype = field.dtype

    if dtype == 'int':
        if isinstance(val, bool):
            raise ValueError(f"Value for field '{field.name}' must be an integer, got bool")
        try:
            coerced = int(val)
        except (ValueError, TypeError):
            raise ValueError(f"Value '{val}' cannot be coerced to int")

        if field.min is not None and coerced < field.min:
            raise ValueError(f"Value {coerced} is below minimum {field.min}")
        if field.max is not None and coerced > field.max:
            raise ValueError(f"Value {coerced} is above maximum {field.max}")
        return coerced

    elif dtype == 'float':
        if isinstance(val, bool):
            raise ValueError(f"Value for field '{field.name}' must be a float, got bool")
        try:
            coerced = float(val)
        except (ValueError, TypeError):
            raise ValueError(f"Value '{val}' cannot be coerced to float")

        if field.min is not None and coerced < field.min:
            raise ValueError(f"Value {coerced} is below minimum {field.min}")
        if field.max is not None and coerced > field.max:
            raise ValueError(f"Value {coerced} is above maximum {field.max}")
        return coerced

    elif dtype == 'bool':
        if isinstance(val, bool):
            return val
        if isinstance(val, str):
            v_low = val.strip().lower()
            if v_low == 'true':
                return True
            elif v_low == 'false':
                return False
        raise ValueError(f"Value '{val}' cannot be coerced to bool")

    elif dtype == 'str':
        coerced = str(val)
        if field.choices is not None and coerced not in field.choices:
            raise ValueError(f"Value '{coerced}' is not a valid choice. Allowed: {field.choices}")
        return coerced

    elif dtype in ('path-file', 'path-dir'):
        return str(val)

    elif dtype == 'enum':
        coerced = str(val)
        if field.choices is not None and coerced not in field.choices:
            raise ValueError(f"Value '{coerced}' is not a valid choice. Allowed: {field.choices}")
        return coerced

    else:
        raise ValueError(f"Unknown dtype '{dtype}'")


def validate_config(submitted: dict, *, secrets: dict[str, str]) -> ValidatedConfig:
    field_errors = {}
    values = {}

    # 1. Validate CONFIG_FIELDS
    for field in CONFIG_FIELDS:
        if field.name in submitted:
            val = submitted[field.name]
            try:
                coerced = coerce_value(val, field)
                values[field.name] = coerced
            except Exception as e:
                field_errors[field.name] = str(e)
        else:
            values[field.name] = field.default

    # 2. Validate ROLES
    for r in ROLES:
        cfg_path = r.config_key
        if cfg_path not in submitted:
            field_errors[cfg_path] = "missing assignment"
            continue

        val = submitted[cfg_path]
        if r.dual:
            if not isinstance(val, (list, tuple)) or len(val) != 2:
                field_errors[cfg_path] = "must be a list of two agents"
                continue

            agent0, agent1 = val
            if agent0 not in PROVIDERS or agent1 not in PROVIDERS:
                field_errors[cfg_path] = "invalid agent choice"
                continue
            if agent0 == agent1:
                field_errors[cfg_path] = "agents must be different"
                continue

            # lock check
            locked_envs = []
            for agent_id in (agent0, agent1):
                p_spec = PROVIDERS[agent_id]
                if p_spec.api_backed:
                    env_var = p_spec.api_key_env
                    if not secrets.get(env_var):
                        locked_envs.append(env_var)
            if locked_envs:
                field_errors[cfg_path] = f"provider locked: set {locked_envs[0]} first"
                continue

            values[cfg_path] = list(val)
        else:
            if not isinstance(val, str):
                field_errors[cfg_path] = "must be a provider-id string"
                continue
            if val not in PROVIDERS:
                field_errors[cfg_path] = f"invalid provider: {val}"
                continue

            p_spec = PROVIDERS[val]
            if p_spec.api_backed:
                env_var = p_spec.api_key_env
                if not secrets.get(env_var):
                    field_errors[cfg_path] = f"provider locked: set {env_var} first"
                    continue

            values[cfg_path] = val

    if field_errors:
        raise ConfigValidationError(field_errors)

    return ValidatedConfig(values)


def set_nested_val(d: dict, dotted_path: str, val: Any) -> None:
    parts = dotted_path.split('.')
    cur = d
    for part in parts[:-1]:
        if part not in cur or not isinstance(cur[part], dict):
            cur[part] = {}
        cur = cur[part]
    cur[parts[-1]] = val


def atomic_save_config(validated: ValidatedConfig, config_path) -> None:
    path = Path(config_path)
    if path.exists():
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f) or {}
        except Exception:
            data = {}
    else:
        data = {}

    if not isinstance(data, dict):
        data = {}

    short_to_dotted_paths = {
        "parallel_cap": "autowork.parallel_cap",
        "min_ram_mb": "autowork.min_ram_mb",
        "cooldown_tier_1": "autowork.cooldown_tier_1",
        "cooldown_tier_2": "autowork.cooldown_tier_2",
        "cooldown_tier_3": "autowork.cooldown_tier_3",
        "antigravity_mode": "synthesis.antigravity_mode",
    }

    for k, val in validated.values.items():
        dotted_path = short_to_dotted_paths.get(k, k)
        set_nested_val(data, dotted_path, val)

    parent_dir = path.parent
    if parent_dir:
        parent_dir.mkdir(parents=True, exist_ok=True)

    tmp_file = NamedTemporaryFile("w", dir=parent_dir, delete=False, suffix=".tmp", encoding="utf-8")
    try:
        yaml.safe_dump(data, tmp_file, default_flow_style=False)
        tmp_file.close()
        os.replace(tmp_file.name, path)
    except Exception:
        try:
            os.unlink(tmp_file.name)
        except OSError:
            pass
        raise
